-- Carregue o CSV do lote em `SEU_PROJETO.logistica._stage_armazens_snapshots` e execute este MERGE.
MERGE `SEU_PROJETO.logistica.armazens_snapshots` T
USING `SEU_PROJETO.logistica._stage_armazens_snapshots` S
ON T.hash_registro = S.hash_registro
WHEN NOT MATCHED THEN
  INSERT (`snapshot_id`, `data_snapshot`, `snapshot_basis`, `data_coleta`, `data_publicacao`, `data_referencia`, `competencia`, `coleta_em_utc`, `source_id`, `source_url`, `arquivo_origem`, `hash_arquivo_sha256`, `arquivo_tamanho_bytes`, `quantidade_armazens`, `capacidade_estatica_total_t`, `capacidade_recepcao_total_t`, `capacidade_expedicao_total_t`, `hash_registro`, `hash_chave_natural`, `status_snapshot`, `motivo_status_snapshot`, `snapshot_baseline`, `validacao_snapshot_em_utc`, `quantidade_armazens_anterior`, `ratio_quantidade_vs_anterior`, `capacidade_estatica_anterior_t`, `ratio_capacidade_vs_anterior`, `ufs_anterior`, `ratio_ufs_vs_anterior`, `sobreposicao_chaves_vs_anterior`, `arquivo_tamanho_anterior_bytes`, `ratio_tamanho_arquivo_vs_anterior`) VALUES (S.`snapshot_id`, S.`data_snapshot`, S.`snapshot_basis`, S.`data_coleta`, S.`data_publicacao`, S.`data_referencia`, S.`competencia`, S.`coleta_em_utc`, S.`source_id`, S.`source_url`, S.`arquivo_origem`, S.`hash_arquivo_sha256`, S.`arquivo_tamanho_bytes`, S.`quantidade_armazens`, S.`capacidade_estatica_total_t`, S.`capacidade_recepcao_total_t`, S.`capacidade_expedicao_total_t`, S.`hash_registro`, S.`hash_chave_natural`, S.`status_snapshot`, S.`motivo_status_snapshot`, S.`snapshot_baseline`, S.`validacao_snapshot_em_utc`, S.`quantidade_armazens_anterior`, S.`ratio_quantidade_vs_anterior`, S.`capacidade_estatica_anterior_t`, S.`ratio_capacidade_vs_anterior`, S.`ufs_anterior`, S.`ratio_ufs_vs_anterior`, S.`sobreposicao_chaves_vs_anterior`, S.`arquivo_tamanho_anterior_bytes`, S.`ratio_tamanho_arquivo_vs_anterior`);
